import{buildScene}from './scene3d.js';
export async function native3DFiles(project,frames,name,onProgress=()=>{}){
 const samples=[];for(let i=0;i<frames;i++){samples.push({segments:buildScene(project.layers,i/frames*project.duration)});onProgress(`สร้าง geometry 3D ${i+1} / ${frames}`);if(i%4===0)await new Promise(r=>setTimeout(r,0));}
 const suffix=crypto.randomUUID().replaceAll('-','').slice(0,10),className='VFXForge3D_'+suffix,shaderName='VFXForge/WorldLines_'+suffix;
 async function source(path){const r=await fetch(path);if(!r.ok)throw Error('โหลด Unity runtime ไม่ได้');return r.text();}
 const [cs,shader]=await Promise.all([source('VFXForge3D.cs.txt'),source('WorldLines.shader.txt')]);
 return[[name+'.world3d.json',JSON.stringify({duration:project.duration,frames:samples})],[className+'.cs',cs.replaceAll('VFXForge3D',className).replaceAll('VFXForge/WorldLines',shaderName)],['WorldLines_'+suffix+'.shader',shader.replaceAll('VFXForge/WorldLines',shaderName)],[name+'.vfxforge.json',JSON.stringify(project,null,2)],['README.md',`# ${project.name} — World-space 3D\n\nUnity 6 + URP. Real X/Y/Z geometry sampled at ${frames/project.duration} FPS (${frames} frames, ${project.duration}s). This is a mesh animation package, not a .vfx graph.\n\n1. Extract this ZIP into Assets in a Unity URP project.\n2. Create an empty GameObject, add the ${className} component.\n3. Drag ${name}.world3d.json into Animation Json.\n4. Create a Material using shader ${shaderName}, assign Effect Material (also ensures shader is retained in player builds).\n5. Press Play. Move the camera around: geometry stays in world space.\n\nThe component builds and caches each frame mesh on first use. Line segments become thin 3D prisms. Colors use additive blending; Alpha mode layers are approximated additively in this native package. Glow in the browser is a preview approximation; add URP Bloom for glow in Unity. Large frame/layer counts increase mesh memory.\n\nBaked mesh frames retain 3D depth but are not editable procedural VFX Graph nodes. No camera is baked into this package. PNG/Shader Graph/VFX Graph export instead bake the chosen camera view onto a quad.\n\nImport/compilation has not been verified in Unity Editor.\n`]];
}
